window.ScripturaLexicons.BDAG_PART_0202 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-01\" data-source=\"BDAG\" data-search=\"κιβώριον, ου, τό substantivo neutro cibório; receptáculo para sementes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κιβώριον, ου, τό</td><td>substantivo neutro</td><td>cibório; receptáculo para sementes</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-02\" data-source=\"BDAG\" data-search=\"κιβωτός, οῦ, ἡ substantivo feminino arca; barco; arca da aliança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κιβωτός, οῦ, ἡ</td><td>substantivo feminino</td><td>arca; barco; arca da aliança</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-03\" data-source=\"BDAG\" data-search=\"κιθάρα, ας, ἡ substantivo feminino lira; harpa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κιθάρα, ας, ἡ</td><td>substantivo feminino</td><td>lira; harpa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-04\" data-source=\"BDAG\" data-search=\"κιθαρίζω verbo tocar lira ou harpa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κιθαρίζω</td><td>verbo</td><td>tocar lira ou harpa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-05\" data-source=\"BDAG\" data-search=\"κιθαρῳδός, οῦ, ὁ substantivo masculino músico que toca lira enquanto canta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κιθαρῳδός, οῦ, ὁ</td><td>substantivo masculino</td><td>músico que toca lira enquanto canta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-06\" data-source=\"BDAG\" data-search=\"Κιλικία, ας, ἡ topônimo Cilícia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κιλικία, ας, ἡ</td><td>topônimo</td><td>Cilícia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-07\" data-source=\"BDAG\" data-search=\"Κίλιξ, ικος, ὁ gentílico cilício BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κίλιξ, ικος, ὁ</td><td>gentílico</td><td>cilício</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-08\" data-source=\"BDAG\" data-search=\"κινδυνεύω verbo correr risco; estar em perigo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κινδυνεύω</td><td>verbo</td><td>correr risco; estar em perigo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-09\" data-source=\"BDAG\" data-search=\"κίνδυνος, ου, ὁ substantivo masculino perigo; risco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κίνδυνος, ου, ὁ</td><td>substantivo masculino</td><td>perigo; risco</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-10\" data-source=\"BDAG\" data-search=\"κινέω verbo mover; agitar; provocar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κινέω</td><td>verbo</td><td>mover; agitar; provocar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-11\" data-source=\"BDAG\" data-search=\"κίνησις, εως, ἡ substantivo feminino movimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κίνησις, εως, ἡ</td><td>substantivo feminino</td><td>movimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-12\" data-source=\"BDAG\" data-search=\"κιννάμωμον, ου, τό substantivo neutro canela BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κιννάμωμον, ου, τό</td><td>substantivo neutro</td><td>canela</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-13\" data-source=\"BDAG\" data-search=\"Κίς, ὁ nome próprio Quis, pai de Saul BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κίς, ὁ</td><td>nome próprio</td><td>Quis, pai de Saul</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-14\" data-source=\"BDAG\" data-search=\"κισσάω verbo desejar intensamente; conceber BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κισσάω</td><td>verbo</td><td>desejar intensamente; conceber</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-15\" data-source=\"BDAG\" data-search=\"κίχρημι verbo emprestar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κίχρημι</td><td>verbo</td><td>emprestar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-16\" data-source=\"BDAG\" data-search=\"κλάδος, ου, ὁ substantivo masculino ramo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κλάδος, ου, ὁ</td><td>substantivo masculino</td><td>ramo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-17\" data-source=\"BDAG\" data-search=\"κλαίω verbo chorar; lamentar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κλαίω</td><td>verbo</td><td>chorar; lamentar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-18\" data-source=\"BDAG\" data-search=\"κλάσις, εως, ἡ substantivo feminino ato de partir; partir do pão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κλάσις, εως, ἡ</td><td>substantivo feminino</td><td>ato de partir; partir do pão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-19\" data-source=\"BDAG\" data-search=\"κλάσμα, ατος, τό substantivo neutro fragmento; pedaço; migalha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κλάσμα, ατος, τό</td><td>substantivo neutro</td><td>fragmento; pedaço; migalha</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0202-20\" data-source=\"BDAG\" data-search=\"Κλαῦδα remissão ver Καῦδα BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κλαῦδα</td><td>remissão</td><td>ver Καῦδα</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0202-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιβώριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κιβώριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span>: receptáculo de sementes do feijão egípcio, cibório (WWeber, Ägypt.-griech. Terrakotten 1914, 63f); também recipiente de forma semelhante (Diod S 1, 34, 6; Nicander, Fgm. 81; Strabo; Didymus Gramm. em Athen. 11, 477e; POxy 105, 18 [II d.C.]; Am 9:1 Sym., Theod.; cf. TestSol PVindob em 18:35 [<span class=\"greek\">κι</span>]<span class=\"greek\">βωρ</span>[<span class=\"greek\">ιον</span>]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:24</a>, variante de leitura (veja N. 26 e edições anteriores), como glosa a <span class=\"greek\">ναοὺς</span> <span class=\"greek\">ἀργυροῦς</span>: <span class=\"greek\">ἴσως</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">κιβώρια</span> <span class=\"greek\">μικρά</span> = santuários de prata, algo como receptáculos semelhantes a pequenos recipientes de sementes.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιβωτός, οῦ, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κιβωτός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ἡ</span> (Aristoph., Lysias e outros; inscrições, papiros, LXX; JosAs 10:9 códice A e 18:3 códices A D G em lugar de <span class=\"greek\">κιβώτιον</span> [códice B]; ParJer 7:8; GrBar 4:11; Just., D. 127, 3), geralmente ‘caixa, cofre’, em nossa literatura em sentidos especializados. ① Embarcação, barco, arca (algo como uma ‘barcaça’ [Moffatt]; latim arca [daí ‘arca’] ‘cofre, caixa’ = <span class=\"hebrew\">תֵּבָה</span>), acerca da arca de Noé (Gen 6:14ff; 4 Macc 15:31; SibOr 1, 266; Theoph. Ant. 3, 19 [p. 240, 23]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:27</a> (ambas Gen 7:7); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:20</a>; 1 Cl 9:4. ② Repositório sagrado, cofre da aliança, arca (<span class=\"hebrew\">אֲרוֹן</span>) no Santo dos Santos: <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">διαθήκης</span>, a arca da aliança (Ex 39:14 e outras passagens; Philo; Jos., Ant. 3, 134 e outras), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:4</a>; também encontrada no templo celestial, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:19</a>.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιθάρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κιθάρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Hom. Hymns, Hdt. e outros; LXX, TestJob, Philo; Jos., Ant. 1, 64; SibOr 8, 119; Ar. 11, 11; Ath. 16, 2): lira, harpa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:8</a>; 14:2. <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, literalmente harpas de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:2</a>, isto é, pertencentes a Deus ou dadas por Deus (cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">σάλπιγγι</span> <span class=\"greek\">θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:16</a>), ou harpas empregadas no louvor a Deus. Talvez a expressão seja uma formação superlativa semítica, grandes harpas, análoga a <span class=\"greek\">ὄρη</span> <span class=\"greek\">θεοῦ</span> = montanhas poderosas, Ps 35:7; cf. 79:11; compare também <span class=\"greek\">ἀστεῖος</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:20</a>, e veja <span class=\"greek\">θεός</span> 3g <span class=\"greek\">β</span>. Com a flauta (veja <span class=\"greek\">αὐλός</span>; Philo, Leg. All. 2, 75; 3, 221), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:7</a>. As cordas da harpa, IEph 4:1; IPhld 1:2.—Kl. Pauly III 1581f; OEANE IV 70–79; veja bibliografia em <span class=\"greek\">κύμβαλον</span>.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιθαρίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κιθαρίζω</span> (<span class=\"greek\">κίθαρις</span>, ‘lira’; Hom. e outros; SIG 578, 18 [II a.C.] <span class=\"greek\">κιθαρίζειν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ψάλλειν</span>; Is 23:16; TestAbr A 10 p. 87, 24 [Stone p. 22]; Jos., C. Ap. 2, 242): tocar lira ou harpa, juntamente com o som da flauta (Dio Chrys. 2, 55; 52 [69], 3; Polyaenus 5, 3, 3; Achmes 207, 16), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:7</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">κιθάρᾳ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:2</a>.—Haifa Museum, Music in Ancient Israel, ’72; SMichaelides, The Music of Ancient Greece, ’78.—DELG s.v. <span class=\"greek\">κιθάρα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιθαρῳδός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κιθαρῳδός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">κιθάρα</span> [acima], <span class=\"greek\">ἀοιδός</span> ‘cantor’; Hdt., Pla.; Diphil. Com. Fgm. 75 Kock [Athen. 6, 247d]; Plut., Mor. 166a; Aelian, VH 4, 2; SIG [índice]; OGI 51, 41 [III a.C.]; 352, 67; IPriene 113, 80; PEdgar 77 [= Sb 6783], 17 [257 a.C.]; Philo; Ar. 11, 1): tocador de lira, harpista que acompanha seu próprio canto ao instrumento (o <span class=\"greek\">κιθαριστής</span> toca o instrumento sem cantar; ambas as palavras aparecem juntas em Philo, Agr. 35; diferenciadas em Diog. L. 3, 88; Aristoxenus, Fgm. 102, remonta o contraste a dois instrumentos distintos: <span class=\"greek\">κίθαρις</span> [= <span class=\"greek\">λύρα</span>] e <span class=\"greek\">κιθάρα</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:2</a>; 18:22.—DELG s.v. <span class=\"greek\">κιθάρα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κιλικία, ας, ἡ</h1><div class=\"entry-meta\"><span>topônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κιλικία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Hdt. e outros; inscrições, LXX; Philo, Leg. ad Gai. 281; Joseph.): Cilícia, província no extremo sudeste da Ásia Menor, cuja capital é Tarso; terra natal de Paulo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:9</a>; 15:23, 41; 21:39; 22:3; 23:34; 27:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:21</a> (sobre a ligação com <span class=\"greek\">Συρία</span>, veja esse verbete); IPhld 11:1.—Ramsay, Hist. Geogr. 361ff; RHeberdey-AWilhelm, Reisen in Kilikien 1896; FSchaffer, Cilicia 1903; VSchultze, Altchristl. Städte u. Landschaften II 2, 1926; AJones, Cities of the East. Rom. Provinces, ’37, 197ff; Pauly-W. XI 385ff; Kl. Pauly III 208f.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κίλιξ, ικος, ὁ</h1><div class=\"entry-meta\"><span>gentílico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κίλιξ</span>, <span class=\"greek\">ικος</span>, <span class=\"greek\">ὁ</span> (Hom. e outros; inscrições [incluindo IGUR 1286, 1; 1361; veja New Docs 4, 173], Joseph., SibOr; Ath. 14, 1): um cilício, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:34</a>, variante de leitura.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινδυνεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κινδυνεύω</span>, imperfeito <span class=\"greek\">ἐκινδύνευον</span> (veja o verbete seguinte; Pind., Hdt. e outros; inscrições, papiros, LXX, TestJud 21:6; Joseph.): estar em perigo, correr risco, em uso absoluto (SIG 708, 8; BGU 423, 7; Is 28:13), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:23</a> (cf. Jos., Vi. 14). <span class=\"greek\">οἱ</span> <span class=\"greek\">κινδυνεύοντες</span>, aqueles que estão em perigo (SIG 570, 4), 1 Cl 59:3. <span class=\"greek\">κ</span>. <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ὥραν</span>, estar em perigo a cada hora (de fato, em risco de perder a vida; cf. <span class=\"greek\">κινδυνεύω</span> em uso absoluto, Diog. L. 9, 57), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:30</a>. <span class=\"greek\">κινδυνεύειν</span> <span class=\"greek\">τινὸς</span> <span class=\"greek\">χάριν</span>, enfrentar perigo por causa de alguém, 1 Cl 55:6.—Seguido de infinitivo (X., Mem. 2, 3, 16; Diod S 12, 51, 1; SIG 852, 32f; 888, 68f; UPZ 161, 10 [119 a.C.]; BGU 530, 12; 30; POxy 44, 9; 3 Macc 5:41; Jos., Ant. 4, 188; Theoph. Ant. 3, 26 [p. 258, 23]; veja B-D-F § 392, 2): <span class=\"greek\">κινδυνεύομεν</span> <span class=\"greek\">ἐγκαλεῖσθαι</span> <span class=\"greek\">στάσεως</span>, corremos o risco de ser acusados de sedição, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:40</a>. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">κινδυνεύει</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέρος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀπελεγμὸν</span> <span class=\"greek\">ἐλθεῖν</span>, há o perigo de que esse nosso ramo de atividade caia em descrédito, versículo 27.—DELG s.v. <span class=\"greek\">κίνδυνος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίνδυνος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κίνδυνος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (veja o verbete anterior; Pind., Hdt.+; inscrições, papiros, LXX; TestJob 15:5; JosAs 26:7; EpArist 199; Jos., Vi. 272; Ath. 21, 2, R. 6 p. 54, 19): perigo, risco, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:35</a> (veja New Docs 3, 58f). Aquilo de que provém o perigo é expresso apenas pelo genitivo (Pla., Euthyd. 279e <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span>, Rep. 1, 332e; Heliod. 2, 4, 1; Hippiatr. II 234, 13 <span class=\"greek\">ποταμῶν</span>; Ps 114:3; Sir 43:24), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:26a</a>; ou por <span class=\"greek\">ἐκ</span>, versículo 26b. As expressões <span class=\"greek\">ἐν</span> <span class=\"greek\">πόλει</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐρημίᾳ</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">θαλάσσῃ</span> (Plut., Mor. 603e <span class=\"greek\">κινδύνους</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">θαλ</span>.), <span class=\"greek\">ἐν</span> <span class=\"greek\">ψευδαδέλφοις</span>, na mesma passagem, c, possuem sentido algo diferente e indicam o lugar onde o perigo se oculta (cf. Ps.-Ael. Aristid. 25, 20 K. = 43 p. 804 D.: <span class=\"greek\">θάνατοι</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">οἰκίας</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">ἱεροῖς</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">θύραις</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">πύλαις</span>; Ps.-Pla., 11ª carta, 358e <span class=\"greek\">κινδυνεύειν</span> <span class=\"greek\">κατά</span> <span class=\"greek\">τε</span> <span class=\"greek\">γῆν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">θάλατταν</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">κινδύνων</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">πορείαις</span> <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">μεστά</span>, ‘enfrentar perigos em terra e no mar, e agora tudo nas viagens está cheio de riscos’). <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">κίνδυνον</span>, em perigo, IEph 12:1; ITr 13:3. <span class=\"greek\">κ</span>. <span class=\"greek\">ὑποφέρειν</span>, incorrer em perigo, 1 Cl 14:2. <span class=\"greek\">κινδύνῳ</span> <span class=\"greek\">ὑποκεῖσθαι</span>, expor-se a risco, 41:4. <span class=\"greek\">κ</span>. <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">ἐπεξεργάζεσθαι</span>, trazer perigo sobre si, 47:7. <span class=\"greek\">παραδοῦναι</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span>., expor-se ao perigo, 55:5; também <span class=\"greek\">παραβαλεῖν</span>, versículo 6. <span class=\"greek\">κινδύνῳ</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἐνδῆσαι</span>, envolver-se em perigo, 59:1. Acerca de enfermidade grave, <span class=\"greek\">εἰς</span> <span class=\"greek\">νόσον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔσχατον</span> <span class=\"greek\">κ</span>., AcPl Ha 4, 16.—B. 1155. DELG. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κινέω</span>, futuro <span class=\"greek\">κινήσω</span>; 1º aoristo <span class=\"greek\">ἐκίνησα</span>; particípio perfeito <span class=\"greek\">κεκινηκώς</span> (Ath.). Na passiva: futuro <span class=\"greek\">κινηθήσομαι</span>, LXX; aoristo <span class=\"greek\">ἐκινήθην</span> (veja o verbete seguinte; Hom.+), ‘mover’. ① Fazer com que alguma coisa seja deslocada de seu lugar habitual ou estabelecido: mover para outro lugar, retirar, <span class=\"greek\">τὶ</span>, alguma coisa (Lysimachus [200 a.C.]: 382 Fgm. 2 Jac.; Diod S 20, 110, 1 <span class=\"greek\">κινῆσαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔθος</span> = pôr fim ao costume; Jos., C. Ap. 2, 272 <span class=\"greek\">τὰ</span> <span class=\"greek\">νόμιμα</span> <span class=\"greek\">κ</span>. = ‘retirar a lei de seu lugar próprio’): <span class=\"greek\">τῷ</span> <span class=\"greek\">δακτύλῳ</span> <span class=\"greek\">φορτία</span>, mover fardos com um único dedo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:4</a> (Artem. 1, 31 p. 32, 18f <span class=\"greek\">φορτία</span> <span class=\"greek\">κινούμενα</span>). <span class=\"greek\">κ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span>, retirar alguma coisa de determinado lugar: <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">λυχνίαν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τόπου</span> <span class=\"greek\">αὐτῆς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:5</a>. Na passiva, 6:14 (cf. Astrampsychus p. 5 linha 12 <span class=\"greek\">εἰ</span> <span class=\"greek\">κινηθήσομαι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τόπου</span> <span class=\"greek\">μοῦ</span> = se perderei meu lugar). ② Fazer alguma coisa entrar em movimento, mover, pôr em movimento. ⓐ Sacudir a cabeça (Hom. e outros; Job 16:4; Da 4:19; Sir 12:18; 13:7; TestJob 30:1): <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλήν</span>, mover a cabeça de um lado a outro como sinal de desprezo e escárnio (Nicol. Dam.: 90 Fgm. 4 p. 335, 18 Jac.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:29</a>; 1 Cl 16:16 (Ps 21:8). ⓑ Produzir agitação, incitar, na passiva (Jos., Ant. 3, 13), de uma situação tumultuosa: <span class=\"greek\">ἐκινήθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πόλις</span> <span class=\"greek\">ὅλη</span>, toda a cidade ficou agitada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:30</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">διδαχῇ</span>, 14:7 D. ③ Estar em movimento, mover-se, deslocar-se, na passiva com sentido intransitivo (Hom. e outros; Gen 7:14, 21 e outras; En 101:8; TestSol 4:17 D; ApcSed 11:10; Philo; Just., D. 127, 2; Tat. 22:2), Hv 4, 1, 9. Como expressão da existência de um ser vivo: <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ζῶμεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κινούμεθα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐσμέν</span>, nele vivemos, nos movemos e existimos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:28</a> (sobre o sentido e a origem da frase, especialmente de <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">κινεῖσθαι</span>, veja Norden, Agn. Th. 19ff; MDibelius, Pls auf. d. Areop. ’39, 26; MPohlenz, Pls u. d. Stoa: ZNW 42, ’49, 69–104, especialmente 88ff.—Talvez <span class=\"greek\">κ</span>. nesta passagem, aparecendo entre ‘viver’ e ‘existir’, enfatize menos ‘mover-se’ do que ‘existência’; cf. Achilles Tat. 2, 37, 1 <span class=\"greek\">τὸ</span> <span class=\"greek\">κινούμενον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">φθορᾷ</span> = ‘aquilo que existe em meio à corruptibilidade’). ④ Fazer alguma coisa acontecer. ⓐ Quanto a circunstâncias externas: causar, provocar (Pla., Rep. 8, 566e <span class=\"greek\">πολέμους</span>; Jos., Bell. 2, 175 <span class=\"greek\">ταραχήν</span>; PParis 68a, 6 <span class=\"greek\">θόρυβος</span> <span class=\"greek\">ἐκινήθη</span>), <span class=\"greek\">στάσεις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:5</a>. ⓑ Quanto a estado interior: mover, motivar (Plut., Cim. 489 [16, 10]; Ael. Aristid. 19, 6 K. = 41 p. 764 D.: <span class=\"greek\">ἐκίνησέν</span> <span class=\"greek\">με</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>; POxy 1121, 16 <span class=\"greek\">τίνι</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">πόθεν</span> <span class=\"greek\">κεινηθέντες</span>; TestAbr; Just., A I, 36, 1; Ath. 9, 1), na passiva seguida de infinitivo (PFlor 58, 15), Dg 11:8 (cf. Ath., R. 12 p. 61, 5 <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τι</span> <span class=\"greek\">κινουμένους</span>).—B. 662. Schmidt, Syn. III 128–49. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίνησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κίνησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (veja o verbete anterior; Pla.+; OGI 543, 15 [II d.C.]; papiros, LXX; TestReub 2:4, variante de leitura; ApcSed 11:3 p. 134, 14 Ja.; EpArist; frequentemente Philo; Jos., Ant. 1, 31; 17, 251; Just., D. 6, 1; Tat. 22, 2; Ath.; Mel., Fgm. 8b [linha 37 Perler]): movimento, <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὕδατος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:3</a>, variante de leitura (Diod S 11, 89, 4 <span class=\"greek\">κίνησις</span>, acerca do movimento da água causado por uma divindade; Epict. 3, 3, 21 <span class=\"greek\">ὅταν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">κινηθῇ</span>). <span class=\"greek\">ἄστρων</span>, Hm 12, 4, 1 (acréscimo do códice Athous).—DELG s.v. <span class=\"greek\">κινέω</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιννάμωμον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κιννάμωμον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (empréstimo semítico, cf. <span class=\"hebrew\">קִנָּמוֹן</span>; veja Hdt. 3, 111; Aristot.; Diod S 2, 49, 3; OGI 214, 59 [III a.C.]; PTebt 190; 250; PSI 628, 8; PGM 13, 100; 358; LXX, En; Jos., Bell. 6, 390; espécie da família tropical das lauráceas: Zohary 202): canela, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:13</a> (variante de leitura <span class=\"greek\">κινάμ</span>.).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κίς, ὁ</h1><div class=\"entry-meta\"><span>nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κίς</span>, <span class=\"greek\">ὁ</span>, indeclinável (também <span class=\"greek\">Κείς</span>, <span class=\"hebrew\">קִישׁ</span>): Quis, pai de Saul (1 Km 9:1 e outras passagens; Jos., Ant. 6, 45 f; 130 [<span class=\"greek\">Κείς</span>]; 56; 62 [<span class=\"greek\">Κείσαιος</span>]; 268 [<span class=\"greek\">Κεῖσος</span>]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:21</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κισσάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κισσάω</span>, 1º aoristo <span class=\"greek\">ἐκίσσησα</span>: desejar ardentemente, ter desejo intenso (Aristoph. e outros; também Just., D. 58, 4 [em lugar de <span class=\"greek\">ἐγκισσάω</span>, Gen 31:10]; acerca dos desejos de grávidas por alimentos incomuns, Aristot. e outros); conceber, engravidar de <span class=\"greek\">τινά</span>, alguém, 1 Cl 18:5 (Ps 50:7).—DELG s.v. 2 <span class=\"greek\">κίσσα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίχρημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κίχρημι</span>, 1º aoristo <span class=\"greek\">ἔχρησα</span> (Hdt. e outros; inscrições, papiros, LXX): emprestar <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, alguma coisa a alguém (Hdt. 3, 58; Plut., Pomp. 634[29, 4]; SIG 241 B, 87; 1 Km 1:28; Jos., Bell. 3, 359), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:5</a>.—DELG s.v. <span class=\"greek\">χρή</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κλάδος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κλάδος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Trag.; Hdt. 7, 19 [<span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλαίης</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κλάδους</span>]+): ramo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:32</a>; 24:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:19</a>; Hs 8, 1, 4; 8, 2, 9; 8, 3, 1. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">κλάδους</span>, produzir ramos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:32</a> (aves sobre os ramos, como em Da 4:12, 14 Theod.). <span class=\"greek\">κόπτειν</span> <span class=\"greek\">κλάδους</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, cortar ramos de algo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:8</a>; Hs 8, 1, 2.—Paulo fala figuradamente (cf. Comp. II 155f [Menand., Fgm. 716 Kock]; Sir 23:25; 40:15; SibOr 5, 50) da raiz e dos ramos da oliveira (Kaibel 368, 7, uma jovem falecida é chamada <span class=\"greek\">κλάδος</span> <span class=\"greek\">ἐλέας</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:16f</a>f, 21. Também em sentido figurado, cristãos ortodoxos são chamados <span class=\"greek\">κλάδοι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span>, ramos da cruz, ITr 11:2.—B. 523. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κλαίω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κλαίω</span> (Hom.+), imperfeito <span class=\"greek\">ἔκλαιον</span>; futuro (B-D-F § 77; Mlt-H. 244) <span class=\"greek\">κλαύσω</span> (TestJob, ApcMos, Just., Tat.) e <span class=\"greek\">κλαύσομαι</span> (LXX; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:9</a>, variante de leitura; Hv 3, 3, 2; Jos., Bell. 1, 628; SibOr 5, 170); 1º aoristo <span class=\"greek\">ἔκλαυσα</span>; médio-passiva <span class=\"greek\">ἐκλαύσθην</span>; futuro <span class=\"greek\">κλαυσθήσομαι</span>, LXX. ① Chorar, derramar lágrimas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.72\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:72</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:31</a>, 33; 20:11, 13, 15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:39</a>; 21:13; 1 Cl 48:1; Hv 4, 1, 7; GJs 3:1, variante de leitura; AcPl Ha 1, 31; 6, 4. <span class=\"greek\">πικρῶς</span> (veja esse verbete), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.75\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:75</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.62\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:62</a>; GJs 13:1; 15:3. <span class=\"greek\">πολύ</span>, intensamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:4</a>. <span class=\"greek\">πολλά</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:24</a> D; <span class=\"greek\">λίαν</span> <span class=\"greek\">κ</span>., chorar amargamente, Hm 3:3. <span class=\"greek\">μὴ</span> <span class=\"greek\">κλαῖε</span>, <span class=\"greek\">μὴ</span> <span class=\"greek\">κλαίετε</span>, não chores, não choreis, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:13</a>; 8:52b; 23:28a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:5</a>. Acerca do pranto pelos mortos (veja <span class=\"greek\">ἀλαλάζω</span> 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:38f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:32</a>; 8:52. <span class=\"greek\">ἐπί</span> com acusativo, sobre (Judg 14:17 A; TestJob 40:11 e outras; veja B-D-F § 233, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:41</a>; 23:28ab. Também <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> (Plut., Mor. 216d; Synes., Ep. 140 p. 277a; Sir 22:11), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:41</a>, variante de leitura (sobre o pranto e lamento pela destruição iminente de Jerusalém, cf. <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πόλει</span> <span class=\"greek\">θρῆνον</span>, de Jesus, filho de Ananias: Jos., Bell. 6, 304–9). Com <span class=\"greek\">κόπτεσθαι</span> (Jos., Ant. 13, 399; sobre lamentar alguém ainda vivo, cf. Tétis por Aquiles, Il. 18, 52–64; Andrômaca por Heitor, 6, 407–39), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:52</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:9</a>; GPt 12:52, 54. Com <span class=\"greek\">λυπεῖσθαι</span> (TestZeb 4:8; ParJer 7:26; Iren. 1, 4, 2 [Harv. I 36, 1]), GPt 14:59. Com <span class=\"greek\">πενθεῖν</span> (POxy 528, 8 <span class=\"greek\">νυκτὸς</span> <span class=\"greek\">κλαίων</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πενθῶν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:11</a>, 15, 19; GPt 7:27.—Como expressão de qualquer sentimento de tristeza, preocupação ou ansiedade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:20</a> (com <span class=\"greek\">θρηνεῖν</span>, como em Iren. 1, 14, 8 [Harv. I 143, 4]); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.30\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:1</a>. (Em oposição a <span class=\"greek\">γελᾶν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:21</a>, 25; GJs 17:2. (Em oposição a <span class=\"greek\">χαίρειν</span>, como em Hippocr., Ep. 17, 49), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:15</a> (cf. Diod S 13, 22, 5); Hv 3, 3, 2. <span class=\"greek\">κλαίων</span> <span class=\"greek\">λέγω</span>, digo com lágrimas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:18</a>; Hv 1, 2, 2. <span class=\"greek\">κλαίουσα</span> <span class=\"greek\">προσεύξομαι</span>, GJs 2:4 (assim códice A). ② Chorar por alguém, lamentar alguém, <span class=\"greek\">τινά</span>, objeto transitivo (desde Hom.; Sb 4313, 15; Jer 8:23; 22:10; 1 Macc 9:20; TestSim 9; ParJer 4:5; ApcEsdr 6:25 p. 32, 4 Tdf.; Ar. 11:3; Just., D. 78, 8; Tat. 8:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:9</a>, variante de leitura (B-D-F § 148, 2; Rob. 475).—MGolden, Did the Ancients Care When Their Children Died?: Greece and Rome 35, ’88, 152–63; IMorris, Death, Ritual and Social Structure in Classical Antiquity ’92.—B. 1129. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κλάσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κλάσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">κλάω</span>; Pla. e outros; Philo). ① Ato de partir, fraturar. ⓐ <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἄρτου</span>, no partir do pão = quando partiu o pão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:35</a>, com referência específica ao ato de Jesus no versículo 30. Mas veja 2 abaixo. ⓑ <span class=\"greek\">ἡ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">σκελῶν</span> <span class=\"greek\">κ</span>., fratura das pernas (veja <span class=\"greek\">σκέλος</span>), Phlm, subscrição, variante de leitura. ② Ato cultual de partir pão: partir o pão, <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἄρτου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:42</a>. Não é possível determinar com certeza se há referência à observância eucarística. Alguns também classificariam <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:35</a> aqui.—TSchermann, D. ‘Brotbrechen’ im Urchristentum: BZ 8, 1910, 33–52; 162–83; JWeiss, D. Urchristentum 1917, 41ff; JGewiess, D. urapostol. Heilsverkünd. nach d. AG ’39, 146–57; JWanke, BZ 18, ’74, 180–92. Veja <span class=\"greek\">ἀγάπη</span> 2 e <span class=\"greek\">εὐχαριστία</span> 3 final.—DELG s.v. <span class=\"greek\">κλάω</span> 1. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κλάσμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κλάσμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (veja <span class=\"greek\">κλάω</span>; Ps.-X., Cyn. 10, 5; Diod S 17, 13, 4; Plut., Tib. Gr. 19, 1; Vett. Val. 110, 31; 34; SIG 2 588, 192; 196; Michel 833; PLond IV, 1431, 26; 36; 1435, 158; LXX; TestSol 5:13; ApcrEzk [Epiph 70, 8]; Jos., Ant. 10, 244): fragmento, pedaço, migalha (cf. Artem. 4, 33 p. 224, 7 e Ezk 13:19, variante de leitura <span class=\"greek\">κλάσματα</span> <span class=\"greek\">ἄρτων</span>), acerca de sobras de pão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:20</a>; 15:37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:43</a>; 8:8, 19f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:12f</a>. Dos pedaços de pão na Ceia do Senhor, D 9:3f (CMoule, JTS 6, ’55, 240–43).—DELG s.v. <span class=\"greek\">κλάω</span> 1. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0202-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κλαῦδα</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Remissão</div><p class=\"entry-text\"><span class=\"greek\">Κλαῦδα</span> veja <span class=\"greek\">Καῦδα</span>.</p></section></article>"};
